/// One test of Project Wycheproof (`ecdsa_*_test.json` and `ecdsa_*_p1363_test.json`):
/// whether the signature `sig` of the message `msg` is valid for the key of its
/// group. A selection of 293 of the 9,767 tests of those 21 files: the cases of
/// each kind of fault that a verifier can miss (arithmetic edge cases, public keys
/// with special coordinates, and every kind of malformed encoding), on each curve,
/// and a few that depend on the hash.
pub(super) struct WycheproofCase {
    pub id: u32,
    pub flags: &'static str,
    pub msg: &'static str,
    pub sig: &'static str,
    pub valid: bool,
}

/// The tests that share a public key. `hash` names the function that hashes the
/// message, and `p1363` says whether the signatures are `r || s` or DER.
pub(super) struct WycheproofGroup {
    pub curve: &'static str,
    pub hash: &'static str,
    pub p1363: bool,
    pub public: &'static str,
    pub cases: &'static [WycheproofCase],
}

