/// Runs `$body` with the type `$d` standing for the hash that `$name` (a name
/// as RFC 6979 and Wycheproof write them) stands for.
macro_rules! for_hash {
    ($name:expr, $d:ident => $body:expr) => {
        match $name {
            "SHA-1" => {
                type $d = crate::sha1::Sha1;
                $body
            }
            "SHA-224" => {
                type $d = crate::sha2::Sha224;
                $body
            }
            "SHA-256" => {
                type $d = crate::sha2::Sha256;
                $body
            }
            "SHA-384" => {
                type $d = crate::sha2::Sha384;
                $body
            }
            "SHA-512" => {
                type $d = crate::sha2::Sha512;
                $body
            }
            other => panic!("no hash named {other}"),
        }
    };
}
pub(super) use for_hash;

/// Runs `$body` with the type `$c` standing for the curve that `$name` (`P-256`)
/// names.
macro_rules! for_curve {
    ($name:expr, $c:ident => $body:expr) => {
        match $name {
            "P-224" => {
                type $c = crate::ec::P224;
                $body
            }
            "P-256" => {
                type $c = crate::ec::P256;
                $body
            }
            "P-384" => {
                type $c = crate::ec::P384;
                $body
            }
            "P-521" => {
                type $c = crate::ec::P521;
                $body
            }
            other => panic!("no curve named {other}"),
        }
    };
}
pub(super) use for_curve;

pub(super) fn unhex(s: &str) -> Vec<u8> {
    assert!(s.len().is_multiple_of(2), "odd number of hex digits");
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}
